class AmalanScreen extends StatefulWidget { const AmalanScreen({super.key,required this.state,required this.onComplete}); final DailyState state; final Future<void> Function(String) onComplete; @override State<AmalanScreen> createState()=>_AmalanScreenState(); }
class _AmalanScreenState extends State<AmalanScreen>{String filter='SEMUA';String? busy;@override Widget build(BuildContext context){final items=filter=='SEMUA'?widget.state.entries:widget.state.entries.where((e)=>e.period==filter).toList();return SafeArea(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Padding(padding:const EdgeInsets.fromLTRB(20,22,20,12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Amalan Hari Ini',style:Theme.of(context).textTheme.headlineLarge?.copyWith(fontSize:34)),const Text('Langkah kecil yang dijaga bersama.'),const SizedBox(height:16),SingleChildScrollView(scrollDirection:Axis.horizontal,child:Row(children:['SEMUA','PAGI','SIANG','SORE','MALAM'].map((f)=>Padding(padding:const EdgeInsets.only(right:8),child:ChoiceChip(label:Text(f[0]+f.substring(1).toLowerCase()),selected:filter==f,onSelected:(_)=>setState(()=>filter=f))).toList()))])),Padding(padding:const EdgeInsets.symmetric(horizontal:20),child:CtJProgress(value:widget.state.percentage)),const SizedBox(height:12),Expanded(child:items.isEmpty?const Center(child:Text('Belum ada amalan untuk waktu ini.')):ListView.builder(padding:const EdgeInsets.symmetric(horizontal:16),itemCount:items.length,itemBuilder:(_,i){final e=items[i];return Card(color:CtJColors.ivory,child:ListTile(contentPadding:const EdgeInsets.symmetric(horizontal:16,vertical:8),leading:CircleAvatar(backgroundColor:e.completed?CtJColors.teal:CtJColors.gold.withOpacity(.3),child:Icon(e.completed?Icons.check:Icons.auto_awesome,color:e.completed?Colors.white:CtJColors.ink)),title:Text(e.title,style:const TextStyle(color:CtJColors.ink,fontWeight:FontWeight.bold)),subtitle:Text(e.note,style:const TextStyle(color:CtJColors.ink)),trailing:busy==e.id?const SizedBox.square(dimension:24,child:CircularProgressIndicator(strokeWidth:2)):IconButton(tooltip:e.completed?'Selesai':'Tandai selesai',onPressed:e.completed?null:()async{setState(()=>busy=e.id);try{await widget.onComplete(e.id);if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Progress diperbarui')));}finally{if(mounted)setState(()=>busy=null);}},icon:Icon(e.completed?Icons.check_circle:Icons.radio_button_unchecked,color:e.completed?CtJColors.teal:CtJColors.ink)));});)]) );}}
